def get_item_asset_filename(cat: str, item_id: str) -> str | None:
    return ITEM_IMAGE_MAP.get(item_id)


def get_item_by_id(cat: str, item_id: str) -> dict | None:
    cat = str(cat).lower().strip()
    item_id = str(item_id).lower().strip()
    if cat in ("avatars", "avatar"):
        for a in AVATARS_CATALOG:
            if a["id"].lower() == item_id: return a
    elif cat in ("swords", "weapons", "weapon"):
        for w in SWORDS_CATALOG:
            if w["id"].lower() == item_id: return w
    elif cat in ("shields", "shield"):
        for s in SHIELDS_CATALOG:
            if s["id"].lower() == item_id: return s
    elif cat in ("support", "auras", "aura"):
        for u in SUPPORT_CATALOG:
            if u["id"].lower() == item_id: return u
    elif cat in ("arrows", "arrow"):
        for arr in ARROWS_CATALOG:
            if arr["id"].lower() == item_id: return arr
    return None
